type VideoPromptContext={shotNo:number;seconds:number;genre:string;style:string;subject:string;action:string;reference:string;camera:string;composition:string;look:string;color:string;lighting:string;material:string;cadence:string;audio:string;continuity:string;output:string;avoid:string};
function formatVideoPrompt(model:string,c:VideoPromptContext){
  if(model==="Seedance 2.0") return `【创作目标】生成一段 ${c.seconds} 秒的${c.genre}叙事镜头，视觉风格为${c.style}。\n【核心表演】${c.action}\n【故事语境】${c.subject}\n【多模态参考】${c.reference}\n【镜头设计】${c.camera}；${c.composition}。\n【视觉与材质】${c.look}；${c.color}；${c.lighting}；${c.material}。\n【叙事节奏】${c.cadence}，本镜只完成一个清晰动作。\n【声音设计】${c.audio}。\n【连续性】${c.continuity}\n【输出参数】${c.output}，24fps，动作和物理反馈自然。\n【限制】${c.avoid}`;
  if(model==="Sora 2") return `A ${c.seconds}-second continuous ${c.genre} scene in ${c.style} style. ${c.action} The world remains spatially coherent and the central subject—${c.subject}—keeps a persistent identity and physical presence. ${c.reference} The camera performs ${c.camera}, composed with ${c.composition}. The image has ${c.look}, ${c.color}, ${c.lighting}, and ${c.material}. Performance rhythm: ${c.cadence}. Objects obey believable weight, inertia, contact and environmental response. Synchronized sound: ${c.audio}. ${c.continuity} Output: ${c.output}.`;
  if(model==="Veo 3.1") return `CINEMATOGRAPHY: ${c.camera}; ${c.composition}.\nSUBJECT: ${c.subject}.\nACTION: ${c.action}\nCONTEXT: ${c.reference}\nSTYLE & AMBIANCE: ${c.look}; ${c.color}; ${c.lighting}; ${c.material}.\nTEMPORAL DIRECTION: ${c.seconds} seconds; ${c.cadence}.\nAMBIENT SOUND: ${c.audio}.\nSFX: physically synchronized with the visible action.\nCONTINUITY: ${c.continuity}\nOUTPUT: ${c.output}.`;
  if(model==="Kling 3.0") return `【自定义分镜 ${String(c.shotNo).padStart(2,"0")}｜${c.seconds}s】\n场景：${c.subject}，${c.genre}，${c.style}。\n角色动作轨迹：${c.action} 动作从明确起始姿态发展至稳定结束姿态，表情与身体重心连续。\n镜头轨迹：${c.camera}；${c.composition}。\n元素参考：${c.reference}\n画面控制：${c.look}；${c.color}；${c.lighting}；${c.material}。\n节奏：${c.cadence}。\n原生音频：${c.audio}，动作音效与画面逐帧同步。\n一致性：${c.continuity}\n输出：${c.output}。`;
  if(model==="Runway Gen-4.5") return `${c.action} ${c.camera}. The environment responds naturally to the subject's movement. ${c.look}. ${c.lighting}. ${c.color}. ${c.cadence}. ${c.output}.`;
  return `[UNIVERSAL VIDEO PROMPT · SHOT ${String(c.shotNo).padStart(2,"0")} · ${c.seconds} SECONDS]\nSUBJECT & ACTION: ${c.action}\nSTORY CONTEXT: ${c.subject}\nREFERENCE: ${c.reference}\nCAMERA: ${c.camera}; ${c.composition}.\nLOOK: ${c.look}; ${c.color}; ${c.lighting}; ${c.material}.\nPERFORMANCE: ${c.cadence}.\nAUDIO: ${c.audio}.\nCONTINUITY: ${c.continuity}\nOUTPUT: ${c.output}.\nAVOID: ${c.avoid}`;
}

function subjectOf(text:string){ return text.trim().replace(/[。！？!?]/g,"").slice(0,30)||"一个意外改变命运的人"; }
function titleOf(text:string,genre:string){ const clean=text.replace(/[，。！？、,.!?\s]/g,""); const clues=["时间","记忆","秘密","消失","重逢","梦","门","信","光","影子"]; const clue=clues.find(x=>clean.includes(x))||clean.slice(0,5)||"未命名"; const pattern:Record<string,(x:string)=>string>={"悬疑惊悚":x=>`消失的${x}`,"科幻未来":x=>`${x}协议`,"治愈情感":x=>`留给${x}的灯`,"古风奇幻":x=>`${x}引`,"都市反转":x=>`${x}背面`,"搞笑脑洞":x=>`今天禁止${x}`}; return `《${pattern[genre](clue)}》`; }
function referenceAnchor(idea:string,image:ImageInfo|null,imageNotes:string){return image?(imageNotes.trim()?`参考图中的“${imageNotes.trim()}”`:`参考图的${image.orientation}构图、${image.tone}明暗和${image.color}主色`):`“${subjectOf(idea).slice(0,14)}”的核心视觉物件`;}
function buildStory(idea:string,genre:string,style:string,image:ImageInfo|null,imageNotes:string):Story{const subject=subjectOf(idea),g=genreProfiles[genre],v=styleProfiles[style],anchor=referenceAnchor(idea,image,imageNotes);const base=g.structure(subject,anchor);return{title:titleOf(idea,genre),logline:g.logline(subject),hook:g.hook(subject),direction:`题材采用「${g.promise}」的叙事机制，节奏为「${g.pacing}」；视觉采用${style}，${v.direction}。${anchor}将作为贯穿全片的视觉母题。`,structure:base.map((x,i)=>[x[0],`${x[1]} ${i===0?`开场按${v.composition}构图。`:i===2?`高潮以${v.cadence}控制动作。`:""}`])};}

function buildShots(idea:string,genre:string,style:string,duration:number,model:string,image:ImageInfo|null,imageNotes:string,lock:boolean):Shot[]{
  const count=Math.max(4,Math.min(8,Math.round(duration/7))); const subject=subjectOf(idea); const each=duration/count; const g=genreProfiles[genre]; const v=styleProfiles[style]; const anchor=referenceAnchor(idea,image,imageNotes); const beats=g.beats(subject,anchor);
  const shotNames:Record<string,string[]>={"电影写实":["细节特写","人物中景","手持跟拍","对话双人景","空间大全景","情绪特写","环境远景","结尾极特写"],"日系动漫":["绘景特写","情绪中景","动态跟拍","关键帧双人景","绘景大全景","侧脸特写","天空远景","定格极特写"],"3D 动画":["材质特写","角色中景","视差跟拍","角色双人景","环境全景","表情特写","空间远景","物件微距"],"赛博朋克":["数据特写","窥视中景","街区跟拍","隔窗双人景","城市大全景","屏幕光特写","天际远景","信号微距"],"水墨国风":["墨迹特写","留白中景","游动画卷","对景双人景","山水远景","静观特写","天地大全景","落墨极近景"],"复古胶片":["胶片细节","4:3 中景","肩扛跟拍","年代双人景","街景全景","柔焦特写","定机远景","胶片定格"]};
  return Array.from({length:count},(_,i)=>{
    const start=Math.round(i*each),end=Math.round((i+1)*each),seconds=Math.max(2,end-start);
    const genreBeat=beats[i];
    const visual=`${genreBeat} ${i%2===0?`画面强调${v.material}。`:`色彩采用${v.palette}，光线采用${v.lighting}。`}`;
    const cameraZh=v.cameraZh[i%v.cameraZh.length],cameraEn=v.cameraEn[i%v.cameraEn.length];
    const reference=image?`Use the attached image as the primary visual source. Preserve ${anchor}, its ${image.orientation} framing, ${image.tone} exposure and ${image.color} dominant palette. Translate it through ${style} without replacing key subjects or spatial relationships.`:`Recur ${anchor} across shots with evolving narrative meaning.`;
    const continuity=lock?"Lock protagonist identity, face, hairstyle, wardrobe, hero props, body scale and palette across every shot.":"Preserve geography, screen direction and lighting progression across adjacent shots.";
    const output=duration<=60?"vertical 9:16, mobile-first focal placement, safe center framing":"cinematic 16:9, layered depth, deliberate negative space";
    const avoid="subtitles, captions, logos, watermarks, flicker, frame warping, duplicate limbs, face drift, random objects, abrupt exposure shifts, style drift, unmotivated camera movement";
    const prompt=formatVideoPrompt(model,{shotNo:i+1,seconds,genre,style,subject,action:genreBeat,reference,camera:cameraEn,composition:v.composition,look:v.look,color:v.palette,lighting:v.lighting,material:v.material,cadence:v.cadence,audio:g.sound[i],continuity,output,avoid});
    return{id:i+1,time:`00:${String(start).padStart(2,"0")}–00:${String(end).padStart(2,"0")}`,shot:shotNames[style][i],visual,camera:cameraZh,audio:g.sound[i],prompt};
  });
}

function BackdropVisual({mode}:{mode:Backdrop}){
  if(mode==="globe") return <div className="scene globe-scene" aria-hidden="true"><div className="globe"><i className="orbit o1"/><i className="orbit o2"/><i className="orbit o3"/><i className="axis"/><span className="gdot d1"/><span className="gdot d2"/><span className="gdot d3"/></div><div className="scene-label">ORBITAL STORY MAP · LIVE</div></div>;
  if(mode==="mind") return <div className="scene mind-scene" aria-hidden="true"><div className="mind-shell"><div className="hemi left"/><div className="hemi right"/>{Array.from({length:14},(_,i)=><i className={`node n${i+1}`} key={i}/>)}{Array.from({length:10},(_,i)=><span className={`synapse s${i+1}`} key={i}/>)}</div><div className="scene-label">NARRATIVE NEURAL FIELD · THINKING</div></div>;
  return null;
}

