  const [story,setStory]=useState(()=>buildStory(sampleIdea,genres[0],styles[0],null,"")); const [shots,setShots]=useState(()=>buildShots(sampleIdea,genres[0],styles[0],30,models[0],null,"",true)); const [generating,setGenerating]=useState(false); const [copied,setCopied]=useState(""); const [notice,setNotice]=useState("示例内容"); const [version,setVersion]=useState(0);
  const [theme,setThemeState]=useState<Theme>("system"); const [themeOpen,setThemeOpen]=useState(false); const [backdrop,setBackdropState]=useState<Backdrop>("none"); const [brandOpen,setBrandOpen]=useState(false); const [profileOpen,setProfileOpen]=useState(false); const [settingsOpen,setSettingsOpen]=useState(false);
  const [image,setImage]=useState<ImageInfo|null>(null); const [imageNotes,setImageNotes]=useState(""); const [uploadError,setUploadError]=useState(""); const fileRef=useRef<HTMLInputElement>(null); const imageFileRef=useRef<HTMLInputElement>(null);
  const [imageConcept,setImageConcept]=useState(sampleImageConcepts["zh-CN"]); const [imagePurpose,setImagePurpose]=useState(imagePurposes[0]); const [imageStyle,setImageStyle]=useState(imageStyles[0]); const [imageModel,setImageModel]=useState(imageModels[0]); const [imageAspect,setImageAspect]=useState(imageAspects[0]); const [imagePrompt,setImagePrompt]=useState(""); const [imagePromptCore,setImagePromptCore]=useState(""); const [imageGenerating,setImageGenerating]=useState(false); const [imageRendering,setImageRendering]=useState(false); const [imageRenderStatus,setImageRenderStatus]=useState(""); const [generatedImage,setGeneratedImage]=useState<GeneratedImage|null>(null); const [imageWorkflow,setImageWorkflow]=useState<ImageWorkflow>("text-to-image"); const [promptReferences,setPromptReferences]=useState<PromptReference[]>([]); const [imageBriefNotes,setImageBriefNotes]=useState(""); const [referenceError,setReferenceError]=useState("");
  const [poseConcept,setPoseConcept]=useState("一名敏捷的未来城市信使，全身角色设计，服装结构清晰，严格匹配骨骼姿态。" ); const [poseStyle,setPoseStyle]=useState(imageStyles[0]); const [poseAspect,setPoseAspect]=useState(imageAspects[1]); const [poseReference,setPoseReference]=useState<PromptReference|null>(null); const [poseResult,setPoseResult]=useState<GeneratedImage|null>(null); const [posePrompt,setPosePrompt]=useState(""); const [poseGenerating,setPoseGenerating]=useState(false); const [poseStatus,setPoseStatus]=useState(""); const poseRigRef=useRef<PoseRigHandle>(null); const poseFileRef=useRef<HTMLInputElement>(null);
  const [providerId,setProviderId]=useState("openrouter"); const [apiBaseUrl,setApiBaseUrl]=useState(providerById("openrouter").baseUrl); const [apiKey,setApiKey]=useState(""); const [generationModel,setGenerationModel]=useState(""); const [availableModels,setAvailableModels]=useState<ModelOption[]>([]); const [modelSearch,setModelSearch]=useState(""); const [detectingModels,setDetectingModels]=useState(false); const [configStatus,setConfigStatus]=useState("正在读取账户配置…"); const [showApiKey,setShowApiKey]=useState(false); const [accountConfig,setAccountConfig]=useState<AccountModelConfig|null>(null);
  const [imageProviderId,setImageProviderId]=useState("runway"); const [imageApiBaseUrl,setImageApiBaseUrl]=useState(imageGenerationProviderById("runway").baseUrl); const [imageApiKey,setImageApiKey]=useState(""); const [imageGenerationModel,setImageGenerationModel]=useState(imageGenerationProviderById("runway").models[0].id); const [showImageApiKey,setShowImageApiKey]=useState(false); const [imageConfigStatus,setImageConfigStatus]=useState("正在读取图片引擎…"); const [accountImageConfig,setAccountImageConfig]=useState<AccountImageConfig|null>(null);
  const savedKeyMatches=Boolean(accountConfig?.hasApiKey&&accountConfig.providerId===providerId&&sameApiEndpoint(accountConfig.apiBaseUrl,apiBaseUrl));
