  const t=(key:string,values:Record<string,string|number>={})=>translate(locale,key,values);

  useEffect(()=>{ const saved=(localStorage.getItem("frame-theme") as Theme|null)||"system"; setThemeState(saved); const media=window.matchMedia("(prefers-color-scheme: dark)"); const apply=()=>{document.documentElement.dataset.theme=saved==="system"?(media.matches?"dark":"light"):saved}; apply(); media.addEventListener("change",apply); return()=>media.removeEventListener("change",apply); },[]);
  useEffect(()=>{ const saved=(localStorage.getItem("frame-backdrop") as Backdrop|null)||"none"; setBackdropState(saved); },[]);
  useEffect(()=>{const saved=localStorage.getItem("frame-locale");const next=preferredLocale(saved||navigator.language);setLocaleState(next);setIdea(current=>Object.values(sampleIdeas).includes(current)?sampleIdeas[next]:current);setImageConcept(current=>Object.values(sampleImageConcepts).includes(current)?sampleImageConcepts[next]:current);document.documentElement.lang=next},[]);
  useEffect(()=>{let cancelled=false;const activeLocale=preferredLocale(localStorage.getItem("frame-locale")||navigator.language);async function restoreAccountConfig(){const savedProvider=localStorage.getItem("frame-provider")||"openrouter";const preset=providerById(savedProvider);const savedBase=localStorage.getItem("frame-api-base")||preset.baseUrl;const savedModel=localStorage.getItem("frame-generation-model")||"";setProviderId(savedProvider);setApiBaseUrl(savedBase);setGenerationModel(savedModel);if(!user){setConfigStatus(translate(activeLocale,"loginSync"));return}setConfigStatus(translate(activeLocale,"restoring"));try{const response=await fetch("/api/model-config",{cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(translate(activeLocale,"readFailed"));if(cancelled)return;if(data.config){applyAccountConfig(data.config);setConfigStatus(translate(activeLocale,"restored"));clearLegacyKeys();return}const legacyKey=sessionStorage.getItem(`frame-api-key:${savedProvider}`)||sessionStorage.getItem("frame-api-key");if(legacyKey&&savedModel){const migrated=await fetch("/api/model-config",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({providerId:savedProvider,apiBaseUrl:savedBase,model:savedModel,apiKey:legacyKey})});const migratedData=await migrated.json();if(!migrated.ok)throw new Error(translate(activeLocale,"saveFailed"));if(cancelled)return;applyAccountConfig(migratedData.config);clearLegacyKeys();setConfigStatus(translate(activeLocale,"migrated"));return}setConfigStatus(translate(activeLocale,"noAccountConfig"))}catch(error){if(!cancelled)setConfigStatus(error instanceof Error?error.message:translate(activeLocale,"readFailed"))} }restoreAccountConfig();return()=>{cancelled=true}},[user]);
