  useEffect(()=>{const onKeyDown=(event:KeyboardEvent)=>{if(event.key==="Escape"){setThemeOpen(false);setLanguageOpen(false);setBrandOpen(false);setProfileOpen(false);setSettingsOpen(false);return}if(!event.altKey||event.ctrlKey||event.metaKey)return;const target=event.target as HTMLElement|null;if(target?.matches("input, textarea, select, [contenteditable='true']"))return;const next=({"1":"story","2":"image","3":"generate","4":"pose"} as const)[event.key as "1"|"2"|"3"|"4"];if(next){event.preventDefault();setWorkspaceMode(next)}};window.addEventListener("keydown",onKeyDown);return()=>window.removeEventListener("keydown",onKeyDown)},[]);
  function clearLegacyKeys(){sessionStorage.removeItem("frame-api-key");Object.keys(sessionStorage).filter(key=>key.startsWith("frame-api-key:")).forEach(key=>sessionStorage.removeItem(key))}
  function applyAccountConfig(config:AccountModelConfig){setAccountConfig(config);setProviderId(config.providerId);setApiBaseUrl(config.apiBaseUrl);setGenerationModel(config.model);setApiKey("");localStorage.setItem("frame-provider",config.providerId);localStorage.setItem("frame-api-base",config.apiBaseUrl);localStorage.setItem("frame-generation-model",config.model)}
