        {imageWorkflow==="text-to-image"&&<><label className="field-label">02 / {t("imageIdea")}</label><div className="textarea-wrap image-textarea"><textarea value={imageConcept} onChange={e=>setImageConcept(e.target.value)} maxLength={500}/><span>{imageConcept.length}/500</span></div></>}
