        {imageWorkflow==="text-to-image"?<div className="workflow-context-card"><i>Aa</i><span><b>{t("workflowText")}</b><small>{t("workflowTextDesc")}</small></span></div>:<div className="reference-manager"><div className="upload-zone compact-upload reference-upload" role="button" tabIndex={0} onClick={()=>imageFileRef.current?.click()} onKeyDown={e=>{if(e.key==="Enter")imageFileRef.current?.click()}} onDragOver={e=>e.preventDefault()} onDrop={onPromptReferenceDrop}><input ref={imageFileRef} type="file" multiple={imageWorkflow==="multi-reference"} accept="image/jpeg,image/png,image/webp" onChange={e=>{void addPromptReferenceFiles(Array.from(e.target.files||[]));e.currentTarget.value=""}}/><span className="upload-icon">＋</span><b>{imageWorkflow==="image-to-image"?t("addSource"):t("addMultiple")}</b><small>JPG / PNG / WebP · 10MB</small></div>{promptReferences.length>0&&<div className={`reference-grid ${imageWorkflow==="image-to-image"?"single":""}`}>{promptReferences.slice(0,imageWorkflow==="image-to-image"?1:6).map((item,index)=><article className="reference-card" key={item.id}><div className="reference-thumb"><img src={item.src} alt={`${t("referenceImage")} ${index+1}`}/><b>{String(index+1).padStart(2,"0")}</b><button onClick={()=>removePromptReference(item.id)} aria-label={t("close")}>×</button></div><div className="reference-card-body"><span>{item.name}</span>{imageWorkflow==="multi-reference"?<label><small>{t("referenceRole")}</small><select value={item.role} onChange={e=>updatePromptReference(item.id,"role",e.target.value)}>{referenceRoles.map(role=><option key={role} value={role}>{referenceRoleLabel(locale,role)}</option>)}</select></label>:<em>{referenceRoleLabel(locale,"source")}</em>}<input value={item.note} onChange={e=>updatePromptReference(item.id,"note",e.target.value)} placeholder={t("referenceNote")}/></div></article>)}</div>}<label className="reference-direction"><span>{t("globalDirection")}</span><textarea value={imageBriefNotes} onChange={e=>setImageBriefNotes(e.target.value)} placeholder={t("globalDirectionPlaceholder")} maxLength={400}/></label></div>}
